-- Sales & Inventory Planning (Phase 6). AI database only (`pln_*`); it never writes the commerce database.
-- EVERY row that holds sales, stock or hierarchy data carries data_source:
--   DSPORTS_LIVE    read from the DSports admin sales feed (real online orders)
--   IMPORTED        weekly store actuals loaded through the controlled import workflow (a person vouches for them)
--   POC_SYNTHETIC   generated by app.planning.demo from the Inventory AI's synthetic history (deterministic, labelled, NOT real business history)
--   POC_REFERENCE   the demonstration store network, stock and supplier reference data (assumed for the POC)
-- Rebuildable: the demo data comes from `POST /v1/planning/demo/seed`; live data from `POST /v1/planning/ingest`.

CREATE TABLE IF NOT EXISTS pln_location (
    id          TEXT PRIMARY KEY,
    name        TEXT        NOT NULL,
    level       TEXT        NOT NULL CHECK (level IN ('REGION', 'ZONE', 'STORE', 'WAREHOUSE')),
    parent_id   TEXT        REFERENCES pln_location (id),
    channel     TEXT        NOT NULL DEFAULT 'STORE' CHECK (channel IN ('STORE', 'ONLINE', 'WAREHOUSE', 'NONE')),
    status      TEXT        NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'CLOSED', 'PLANNED')),
    opened_on   DATE,
    timezone    TEXT,
    size_factor NUMERIC(6,3) NOT NULL DEFAULT 1,           -- relative trading size (a planning input, not a result)
    data_source TEXT        NOT NULL DEFAULT 'POC_REFERENCE',
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_pln_location_parent ON pln_location (parent_id);

CREATE TABLE IF NOT EXISTS pln_ingest_run (
    id               UUID PRIMARY KEY,
    started_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    finished_at      TIMESTAMPTZ,
    status           TEXT        NOT NULL DEFAULT 'RUNNING' CHECK (status IN ('RUNNING', 'SUCCEEDED', 'FAILED')),
    mode             TEXT        NOT NULL DEFAULT 'INCREMENTAL',   -- INCREMENTAL | BACKFILL
    requested_by     TEXT,
    cursor_updated_at TIMESTAMPTZ,
    cursor_line_id   UUID,
    lines_read       INTEGER     NOT NULL DEFAULT 0,
    lines_changed    INTEGER     NOT NULL DEFAULT 0,
    lines_unchanged  INTEGER     NOT NULL DEFAULT 0,
    lines_excluded   INTEGER     NOT NULL DEFAULT 0,
    weeks_touched    INTEGER     NOT NULL DEFAULT 0,
    detail           JSONB       NOT NULL DEFAULT '{}'::jsonb,
    error            TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_pln_ingest_running ON pln_ingest_run ((TRUE)) WHERE status = 'RUNNING';

-- The raw sold lines with the sales convention already applied (app.planning.conventions), so aggregates are a plain SUM and reconcile to the lines.
CREATE TABLE IF NOT EXISTS pln_sales_line (
    line_id            UUID PRIMARY KEY,
    order_id           UUID        NOT NULL,
    order_number       TEXT,
    product_id         UUID        NOT NULL,
    sku                TEXT,
    quantity           INTEGER     NOT NULL,
    order_status       TEXT        NOT NULL,
    placed_at          TIMESTAMPTZ NOT NULL,
    cancelled_at       TIMESTAMPTZ,
    currency           TEXT        NOT NULL DEFAULT 'INR',
    unit_price         NUMERIC(12,2),
    line_total         NUMERIC(14,2),
    allocated_discount NUMERIC(14,2),
    approved_return_qty INTEGER    NOT NULL DEFAULT 0,
    ship_city          TEXT,
    ship_state         TEXT,
    location_id        TEXT        NOT NULL,
    week_start         DATE        NOT NULL,
    counted            BOOLEAN     NOT NULL,
    gross_units        INTEGER     NOT NULL DEFAULT 0,
    cancelled_units    INTEGER     NOT NULL DEFAULT 0,
    returned_units     INTEGER     NOT NULL DEFAULT 0,
    net_units          INTEGER     NOT NULL DEFAULT 0,
    gross_revenue      NUMERIC(14,2) NOT NULL DEFAULT 0,
    discount           NUMERIC(14,2) NOT NULL DEFAULT 0,
    net_revenue        NUMERIC(14,2) NOT NULL DEFAULT 0,
    source_updated_at  TIMESTAMPTZ NOT NULL,
    ingested_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    data_source        TEXT        NOT NULL DEFAULT 'DSPORTS_LIVE'
);
CREATE INDEX IF NOT EXISTS ix_pln_line_key ON pln_sales_line (product_id, location_id, week_start);
CREATE INDEX IF NOT EXISTS ix_pln_line_week ON pln_sales_line (week_start);

CREATE TABLE IF NOT EXISTS pln_sales_week (
    product_id      UUID        NOT NULL,
    location_id     TEXT        NOT NULL REFERENCES pln_location (id),
    week_start      DATE        NOT NULL,
    data_source     TEXT        NOT NULL,
    gross_units     INTEGER     NOT NULL DEFAULT 0,
    cancelled_units INTEGER     NOT NULL DEFAULT 0,
    returned_units  INTEGER     NOT NULL DEFAULT 0,
    net_units       INTEGER     NOT NULL DEFAULT 0,
    gross_revenue   NUMERIC(14,2) NOT NULL DEFAULT 0,
    discount        NUMERIC(14,2) NOT NULL DEFAULT 0,
    net_revenue     NUMERIC(14,2) NOT NULL DEFAULT 0,
    line_count      INTEGER     NOT NULL DEFAULT 0,
    stockout_days   INTEGER,                                  -- days of the week with stock cut demand (context; NULL = unknown)
    aggregated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (product_id, location_id, week_start, data_source)
);
CREATE INDEX IF NOT EXISTS ix_pln_week_week ON pln_sales_week (week_start, data_source);
CREATE INDEX IF NOT EXISTS ix_pln_week_loc ON pln_sales_week (location_id, week_start);

-- How far each source is complete: a week is CLOSED only when its last day is on or before this date.
CREATE TABLE IF NOT EXISTS pln_data_through (
    data_source  TEXT PRIMARY KEY,
    data_through DATE        NOT NULL,
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS pln_stock_position (
    product_id  UUID    NOT NULL,
    location_id TEXT    NOT NULL REFERENCES pln_location (id),
    as_of       DATE    NOT NULL,
    on_hand     INTEGER NOT NULL CHECK (on_hand >= 0),
    reserved    INTEGER NOT NULL DEFAULT 0 CHECK (reserved >= 0),
    data_source TEXT    NOT NULL DEFAULT 'POC_SYNTHETIC',
    PRIMARY KEY (product_id, location_id)
);

CREATE TABLE IF NOT EXISTS pln_incoming (
    id          UUID PRIMARY KEY,
    product_id  UUID    NOT NULL,
    location_id TEXT    NOT NULL REFERENCES pln_location (id),
    qty         INTEGER NOT NULL CHECK (qty > 0),
    eta         DATE    NOT NULL,
    ref         TEXT,
    data_source TEXT    NOT NULL DEFAULT 'POC_SYNTHETIC'
);
CREATE INDEX IF NOT EXISTS ix_pln_incoming_key ON pln_incoming (product_id, location_id);

CREATE TABLE IF NOT EXISTS pln_forecast_run (
    id             UUID PRIMARY KEY,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by     TEXT,
    source         TEXT        NOT NULL,                      -- POC_SYNTHETIC | DSPORTS_LIVE (the actuals the model learned from)
    as_of_week     DATE        NOT NULL,                      -- the last CLOSED week of history used
    first_week     DATE        NOT NULL,
    horizon_weeks  INTEGER     NOT NULL,
    model_version  TEXT        NOT NULL,
    status         TEXT        NOT NULL DEFAULT 'RUNNING' CHECK (status IN ('RUNNING', 'SUCCEEDED', 'FAILED')),
    n_series       INTEGER     NOT NULL DEFAULT 0,
    n_ok           INTEGER     NOT NULL DEFAULT 0,
    n_fallback     INTEGER     NOT NULL DEFAULT 0,
    n_insufficient INTEGER     NOT NULL DEFAULT 0,
    selection      JSONB       NOT NULL DEFAULT '{}'::jsonb,   -- the method chosen per volume bucket and why (backtest WAPE of every candidate)
    features       JSONB       NOT NULL DEFAULT '{}'::jsonb,   -- which inputs the model used and which it did not
    duration_ms    INTEGER,
    error          TEXT,
    is_current     BOOLEAN     NOT NULL DEFAULT FALSE
);
CREATE INDEX IF NOT EXISTS ix_pln_run_current ON pln_forecast_run (source, is_current);

CREATE TABLE IF NOT EXISTS pln_forecast_series (
    run_id        UUID NOT NULL REFERENCES pln_forecast_run (id) ON DELETE CASCADE,
    product_id    UUID NOT NULL,
    location_id   TEXT NOT NULL,
    method        TEXT NOT NULL,
    bucket        TEXT,
    confidence    TEXT NOT NULL CHECK (confidence IN ('HIGH', 'MEDIUM', 'LOW', 'NONE')),
    status        TEXT NOT NULL CHECK (status IN ('OK', 'FALLBACK', 'INSUFFICIENT_DATA')),
    reason        TEXT,
    history_weeks INTEGER NOT NULL DEFAULT 0,
    zero_share    DOUBLE PRECISION,
    inputs        JSONB NOT NULL DEFAULT '{}'::jsonb,
    PRIMARY KEY (run_id, product_id, location_id)
);

CREATE TABLE IF NOT EXISTS pln_forecast (
    run_id      UUID NOT NULL REFERENCES pln_forecast_run (id) ON DELETE CASCADE,
    product_id  UUID NOT NULL,
    location_id TEXT NOT NULL,
    week_start  DATE NOT NULL,
    horizon     INTEGER NOT NULL,
    forecast    NUMERIC(12,3) NOT NULL CHECK (forecast >= 0),
    lo          NUMERIC(12,3),
    hi          NUMERIC(12,3),
    baseline    NUMERIC(12,3),                                -- the simple baseline for the same week (trailing mean), for comparison
    PRIMARY KEY (run_id, product_id, location_id, week_start)
);
CREATE INDEX IF NOT EXISTS ix_pln_forecast_week ON pln_forecast (run_id, week_start);

CREATE TABLE IF NOT EXISTS pln_eval (
    run_id        UUID NOT NULL REFERENCES pln_forecast_run (id) ON DELETE CASCADE,
    scope         TEXT NOT NULL,                              -- OVERALL | CATEGORY | SPORT | REGION | STORE | BUCKET | METHOD
    scope_key     TEXT NOT NULL,
    model         TEXT NOT NULL,
    horizon_group TEXT NOT NULL,                              -- ALL | H1 | H2_4 | H5_8 | H9_PLUS
    n_obs         INTEGER NOT NULL,
    n_series      INTEGER NOT NULL,
    actual_units  DOUBLE PRECISION NOT NULL,
    wape          DOUBLE PRECISION,
    bias          DOUBLE PRECISION,                           -- sum(forecast - actual) / sum(actual): positive = over-forecast
    mae           DOUBLE PRECISION,
    baseline_wape DOUBLE PRECISION,
    sufficient    BOOLEAN NOT NULL,
    PRIMARY KEY (run_id, scope, scope_key, model, horizon_group)
);

CREATE TABLE IF NOT EXISTS pln_plan (
    id              UUID PRIMARY KEY,
    name            TEXT        NOT NULL,
    fy              INTEGER     NOT NULL,
    first_week      DATE        NOT NULL,
    last_week       DATE        NOT NULL,
    source          TEXT        NOT NULL,                     -- the data scope the plan was built on
    forecast_run_id UUID REFERENCES pln_forecast_run (id),
    scope           JSONB       NOT NULL DEFAULT '{}'::jsonb, -- {sport, category, region, store} filters the plan covers
    status          TEXT        NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'SUBMITTED', 'UNDER_REVIEW', 'APPROVED', 'PUBLISHED', 'REJECTED', 'RETURNED', 'SUPERSEDED')),
    version         INTEGER     NOT NULL DEFAULT 1,           -- bumped on every state change and every edit (optimistic locking)
    revision        INTEGER     NOT NULL DEFAULT 1,           -- the plan's own revision number (a revised plan is a NEW row with revision + 1)
    parent_plan_id  UUID REFERENCES pln_plan (id),
    created_by      TEXT        NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    submitted_by    TEXT,
    submitted_at    TIMESTAMPTZ,
    decided_by      TEXT,
    decided_at      TIMESTAMPTZ,
    published_by    TEXT,
    published_at    TIMESTAMPTZ,
    note            TEXT
);
CREATE INDEX IF NOT EXISTS ix_pln_plan_status ON pln_plan (status, created_at);

-- model_forecast is the immutable snapshot of the model's number at plan creation. The manager's forecast, the target and the approved forecast are separate columns.
CREATE TABLE IF NOT EXISTS pln_plan_line (
    plan_id           UUID    NOT NULL REFERENCES pln_plan (id) ON DELETE CASCADE,
    product_id        UUID    NOT NULL,
    location_id       TEXT    NOT NULL,
    week_start        DATE    NOT NULL,
    model_forecast    NUMERIC(12,3),                          -- NULL: the model had no forecast for it (insufficient data)
    model_lo          NUMERIC(12,3),
    model_hi          NUMERIC(12,3),
    confidence        TEXT,
    manager_forecast  NUMERIC(12,3) CHECK (manager_forecast IS NULL OR manager_forecast >= 0),
    target_units      NUMERIC(12,3) CHECK (target_units IS NULL OR target_units >= 0),
    approved_forecast NUMERIC(12,3),                          -- set when the plan is approved: the manager's forecast if there is one, else the model's
    adj_reason        TEXT,
    adj_note          TEXT,
    adj_by            TEXT,
    adj_at            TIMESTAMPTZ,
    line_version      INTEGER NOT NULL DEFAULT 1,
    PRIMARY KEY (plan_id, product_id, location_id, week_start)
);
CREATE INDEX IF NOT EXISTS ix_pln_line_plan_loc ON pln_plan_line (plan_id, location_id, week_start);

CREATE TABLE IF NOT EXISTS pln_audit (
    id          BIGSERIAL PRIMARY KEY,
    ts          TIMESTAMPTZ NOT NULL DEFAULT now(),
    actor_hash  TEXT        NOT NULL,
    roles       TEXT,
    entity      TEXT        NOT NULL,                         -- PLAN | PLAN_LINE | ACTUAL | ALLOCATION | TRANSFER | SCENARIO | PILOT | INGEST | FORECAST | SCOPE | DEMO | ACCESS
    entity_id   TEXT,
    action      TEXT        NOT NULL,
    before      JSONB,
    after       JSONB,
    reason      TEXT,
    correlation_id TEXT
);
CREATE INDEX IF NOT EXISTS ix_pln_audit_entity ON pln_audit (entity, entity_id, ts);

-- Store and region scope: a STORE_MANAGER / REGIONAL_MANAGER sees and edits only these locations (and everything under a region or zone granted here).
CREATE TABLE IF NOT EXISTS pln_scope (
    actor_hash  TEXT        NOT NULL,
    location_id TEXT        NOT NULL REFERENCES pln_location (id),
    granted_by  TEXT        NOT NULL,
    granted_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (actor_hash, location_id)
);

CREATE TABLE IF NOT EXISTS pln_import_batch (
    batch_id     TEXT PRIMARY KEY,                            -- idempotency key chosen by the importer: the same batch twice changes nothing
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by   TEXT        NOT NULL,
    rows_total   INTEGER     NOT NULL,
    rows_applied INTEGER     NOT NULL,
    data_through DATE,
    note         TEXT
);

-- A correction never overwrites an authoritative actual: it is a separate, approved delta that reports show next to it.
CREATE TABLE IF NOT EXISTS pln_actual_adjustment (
    id            UUID PRIMARY KEY,
    product_id    UUID        NOT NULL,
    location_id   TEXT        NOT NULL REFERENCES pln_location (id),
    week_start    DATE        NOT NULL,
    delta_units   INTEGER     NOT NULL CHECK (delta_units <> 0),
    delta_revenue NUMERIC(14,2),
    reason_code   TEXT        NOT NULL,
    note          TEXT        NOT NULL,
    status        TEXT        NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED')),
    requested_by  TEXT        NOT NULL,
    requested_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    decided_by    TEXT,
    decided_at    TIMESTAMPTZ,
    decision_note TEXT
);
CREATE INDEX IF NOT EXISTS ix_pln_adj_key ON pln_actual_adjustment (product_id, location_id, week_start, status);

CREATE TABLE IF NOT EXISTS pln_alloc_rec (
    id             UUID PRIMARY KEY,
    plan_id        UUID NOT NULL REFERENCES pln_plan (id) ON DELETE CASCADE,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    product_id     UUID NOT NULL,
    location_id    TEXT NOT NULL,
    as_of          DATE NOT NULL,
    status         TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'APPROVED', 'REJECTED', 'SUPERSEDED')),
    action         TEXT NOT NULL,                              -- ORDER | EXPEDITE_INCOMING | TRANSFER_IN | NONE | REVIEW
    risk_level     TEXT,
    required_stock INTEGER,
    on_hand        INTEGER,
    reserved       INTEGER,
    incoming       INTEGER,
    shortage       INTEGER,
    surplus        INTEGER,
    recommended_qty INTEGER,
    order_by       DATE,
    arrival_date   DATE,
    safety_stock   INTEGER,
    coverage_days  DOUBLE PRECISION,
    confidence     TEXT,
    reason         TEXT,
    detail         JSONB NOT NULL DEFAULT '{}'::jsonb,
    decided_by     TEXT,
    decided_at     TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS ix_pln_alloc_plan ON pln_alloc_rec (plan_id, status);

CREATE TABLE IF NOT EXISTS pln_transfer_rec (
    id              UUID PRIMARY KEY,
    plan_id         UUID NOT NULL REFERENCES pln_plan (id) ON DELETE CASCADE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    product_id      UUID NOT NULL,
    from_location   TEXT NOT NULL,
    to_location     TEXT NOT NULL,
    qty             INTEGER NOT NULL CHECK (qty > 0),
    lead_days       INTEGER NOT NULL,
    arrival_date    DATE,
    status          TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'APPROVED', 'REJECTED', 'SUPERSEDED')),
    reason          TEXT,
    avoids_order_qty INTEGER,
    detail          JSONB NOT NULL DEFAULT '{}'::jsonb,
    decided_by      TEXT,
    decided_at      TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS ix_pln_transfer_plan ON pln_transfer_rec (plan_id, status);

CREATE TABLE IF NOT EXISTS pln_scenario (
    id         UUID PRIMARY KEY,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT        NOT NULL,
    plan_id    UUID REFERENCES pln_plan (id) ON DELETE SET NULL,
    name       TEXT        NOT NULL,
    kind       TEXT        NOT NULL,
    params     JSONB       NOT NULL,
    results    JSONB       NOT NULL,
    status     TEXT        NOT NULL DEFAULT 'SIMULATION' CHECK (status IN ('SIMULATION', 'ADOPTED')),
    adopted_by TEXT,
    adopted_at TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS pln_pilot (
    id             UUID PRIMARY KEY,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by     TEXT        NOT NULL,
    opportunity_id UUID        NOT NULL,                       -- a Phase 5 record (src_opportunities); the plan never changes it
    product_name   TEXT        NOT NULL,
    status         TEXT        NOT NULL DEFAULT 'PROPOSED' CHECK (status IN ('PROPOSED', 'APPROVED', 'RUNNING', 'EXPAND', 'CONTINUE_TESTING', 'DISCONTINUE', 'CANCELLED')),
    stores         JSONB       NOT NULL,                       -- [{location_id, qty}]
    duration_weeks INTEGER     NOT NULL,
    estimate       JSONB       NOT NULL,                       -- weekly units per store: range, comparables, confidence, assumptions
    observations   JSONB       NOT NULL DEFAULT '[]'::jsonb,   -- [{week_start, location_id, units, available_days}] entered by a person
    decided_by     TEXT,
    decided_at     TIMESTAMPTZ,
    note           TEXT
);

-- AI-assisted planning analysis (Sales & Inventory Planning): a persisted, reproducible record of what was analysed, with which data and model, and what each finding was based on.
-- Findings are computed by deterministic code from stored records; `summary` is optional LLM wording that is only kept when every number in it is present in the findings.
CREATE TABLE IF NOT EXISTS pln_analysis (
    id               UUID PRIMARY KEY,
    plan_id          UUID NOT NULL REFERENCES pln_plan (id) ON DELETE CASCADE,
    created_by       TEXT NOT NULL,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    source           TEXT NOT NULL,                              -- the plan's data scope (DSPORTS_LIVE | POC_SYNTHETIC)
    filters          JSONB NOT NULL DEFAULT '{}'::jsonb,
    data_through     DATE,
    forecast_run_id  UUID,
    model_version    TEXT,
    plan_version     INTEGER,
    summary          TEXT,
    summary_source   TEXT NOT NULL DEFAULT 'RULES' CHECK (summary_source IN ('RULES', 'LLM')),
    llm              JSONB NOT NULL DEFAULT '{}'::jsonb,         -- {used, model, tokensIn, tokensOut, grounded, error}
    findings         JSONB NOT NULL DEFAULT '[]'::jsonb,
    unavailable      JSONB NOT NULL DEFAULT '[]'::jsonb          -- analyses that could not be run, and why
);
CREATE INDEX IF NOT EXISTS ix_pln_analysis_plan ON pln_analysis (plan_id, created_at DESC);

CREATE TABLE IF NOT EXISTS pln_analysis_action (
    id           BIGSERIAL PRIMARY KEY,
    analysis_id  UUID NOT NULL REFERENCES pln_analysis (id) ON DELETE CASCADE,
    finding_id   TEXT NOT NULL,
    action       TEXT NOT NULL CHECK (action IN ('ADOPTED', 'DISMISSED')),
    actor_hash   TEXT NOT NULL,
    at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    detail       JSONB NOT NULL DEFAULT '{}'::jsonb
);
CREATE INDEX IF NOT EXISTS ix_pln_analysis_action ON pln_analysis_action (analysis_id, finding_id);